  if (live && isPlaceholder(config.slack.webhookUrl)) warnings.push('Live mode without SLACK_WEBHOOK_URL: findings are only logged.');
  if (!config.dryRun && !config.flagWritesEnabled) warnings.push('DRY_RUN=false but FLAG_WRITES_ENABLED is not true, so the guard reports findings without writing flags.');
  if (!config.dryRun && config.flagWritesEnabled && active.every((rule) => !rule.flag)) warnings.push('FLAG_WRITES_ENABLED=true but every rule has "flag": false, so nothing is written.');
  return { errors, warnings };
}

// ---- src/core/integrity.js (embedded by scripts/build-workflow.js) ----
/**
 * The integrity engine: pure functions that turn records, associations and target lookups
 * into findings, a report and a flag-write plan. No network access happens here.
 */

const STATUS = Object.freeze({
  HEALTHY: 'healthy',
  UNVERIFIED: 'unverified',
  AT_RISK: 'at_risk',
  CONFLICT: 'conflict',
  ORPHANED: 'orphaned',
});

const STATUS_RANK = Object.freeze({ healthy: 0, unverified: 1, at_risk: 2, conflict: 3, orphaned: 4 });

const MISSING_CODES = Object.freeze([
  'missing_association',
  'label_mismatch',
  'dangling_association',
  'invalid_parent',
  'insufficient_associations',
]);

const ISSUES_MAX_LENGTH = 1000;

function propertyValue(properties, name) {
  if (!properties) return '';
  const raw = properties[name];
  return raw === undefined || raw === null ? '' : String(raw).trim();
}

function matchesCondition(properties, condition) {
  const value = propertyValue(properties, condition.property);
  if (condition.isEmpty !== undefined) return condition.isEmpty ? value === '' : value !== '';
  if (Array.isArray(condition.in)) return condition.in.includes(value);
  if (Array.isArray(condition.notIn)) return !condition.notIn.includes(value);
  return false;
}

function matchesAllConditions(properties, conditions) {
  return (conditions || []).every((condition) => matchesCondition(properties, condition));
}

function matchesAnyCondition(properties, conditions) {
  return (conditions || []).some((condition) => matchesCondition(properties, condition));
}

function recordCreatedAt(record) {
  const raw = record.createdAt || (record.properties && record.properties.hs_createdate);
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : null;
}

/** Returns "excluded", "grace" or "evaluate". */
function classifyRecord(record, rule, now, settings) {
  if (rule.onlyWhen.length && !matchesAllConditions(record.properties, rule.onlyWhen)) return 'excluded';
  if (rule.skipWhen.length && matchesAnyCondition(record.properties, rule.skipWhen)) return 'excluded';
  const created = recordCreatedAt(record);
  if (created !== null && settings.gracePeriodHours > 0 && now - created < settings.gracePeriodHours * 3600000) return 'grace';
  return 'evaluate';
}

function requiredObjectTypes(rule) {
  return [...new Set(rule.requirements.map((requirement) => requirement.toObjectType))];
}

function matchesAssociationType(association, requirement) {
  if (requirement.associationTypeId === null || requirement.associationTypeId === undefined) return true;
  return (association.types || []).some((type) => Number(type.typeId) === requirement.associationTypeId
    && (!requirement.associationCategory || type.category === requirement.associationCategory));
}

/** Evaluates one requirement for one record and returns a violation or null. */
function evaluateRequirement(record, requirement, associations, targetIndex) {
  if (requirement.when.length && !matchesAllConditions(record.properties, requirement.when)) return null;
  const all = associations || [];
  const labeled = all.filter((association) => matchesAssociationType(association, requirement));
  let dangling = 0;
  let invalid = 0;
  let valid = 0;
  for (const association of labeled) {
    const id = String(association.toObjectId);
    if (requirement.verifyTargets && targetIndex && targetIndex.requested[id] && !targetIndex.unknown[id]) {
      const properties = targetIndex.found[id];
      if (properties === undefined) {
        dangling += 1;
        continue;
      }
      if (requirement.targetWhen.length && !matchesAllConditions(properties, requirement.targetWhen)) {
        invalid += 1;
        continue;
      }
    }
    valid += 1;
  }
  const base = {
    requirementKey: requirement.key,
    requirementLabel: requirement.label,
    toObjectType: requirement.toObjectType,
    associationLabel: requirement.associationLabel,
    severity: requirement.severity,
    min: requirement.min,
    max: requirement.max,
    validCount: valid,
    associatedCount: all.length,
    labeledCount: labeled.length,
    danglingCount: dangling,
    invalidCount: invalid,
  };
  if (valid < requirement.min) {
    let code = 'insufficient_associations';
    if (all.length === 0) code = 'missing_association';
    else if (labeled.length === 0) code = 'label_mismatch';
    else if (dangling > 0) code = 'dangling_association';
    else if (invalid > 0) code = 'invalid_parent';
    return { code, ...base };
  }
  if (requirement.max !== null && valid > requirement.max) return { code: 'too_many_associations', ...base };
  return null;
}

function statusFromViolations(violations) {
  const critical = violations.filter((violation) => violation.severity === 'critical');
  if (critical.some((violation) => MISSING_CODES.includes(violation.code))) return STATUS.ORPHANED;
  if (critical.length) return STATUS.CONFLICT;
  if (violations.length) return STATUS.AT_RISK;
  return STATUS.HEALTHY;
}

function describeViolation(violation) {
  const target = violation.requirementLabel;
  const labelText = violation.associationLabel ? ` labelled "${violation.associationLabel}"` : '';
  const need = `needs at least ${violation.min}`;
  switch (violation.code) {
    case 'missing_association':
      return `${target}: no association (${need})`;
    case 'label_mismatch':
      return `${target}: ${violation.associatedCount} associated but none${labelText} (${need})`;
    case 'dangling_association':
      return `${target}: ${violation.danglingCount} associated record(s) no longer exist (${violation.validCount} valid, ${need})`;
    case 'invalid_parent':
      return `${target}: ${violation.invalidCount} associated record(s) fail the parent criteria (${violation.validCount} valid, ${need})`;
    case 'insufficient_associations':
      return `${target}: ${violation.validCount}${labelText} associated (${need})`;
    case 'too_many_associations':
      return `${target}: ${violation.validCount}${labelText} associated (allows at most ${violation.max})`;
    default:
      return `${target}: ${violation.code}`;
  }
}

function formatIssues(violations) {
  const text = violations.map(describeViolation).join('; ');
  return text.length > ISSUES_MAX_LENGTH ? `${text.slice(0, ISSUES_MAX_LENGTH - 3)}...` : text;
}

function evaluateRecord(record, rule, recordAssociations, targets) {
  const violations = [];
  for (const requirement of rule.requirements) {
    const violation = evaluateRequirement(record, requirement, recordAssociations[requirement.toObjectType], targets[requirement.toObjectType]);
    if (violation) violations.push(violation);
  }
  return { status: statusFromViolations(violations), violations };
}

function emptyCounts() {
  return { scanned: 0, evaluated: 0, skippedGrace: 0, skippedExcluded: 0, healthy: 0, atRisk: 0, conflict: 0, orphaned: 0, unverified: 0 };
}

const COUNT_KEY = { healthy: 'healthy', at_risk: 'atRisk', conflict: 'conflict', orphaned: 'orphaned', unverified: 'unverified' };

/**
 * dataset = {
 *   records:      { [ruleKey]: { records: [{ id, createdAt, properties }], truncated } },
 *   associations: { [ruleKey]: { [toObjectType]: { requested, byFromId, truncatedIds, errorIds } } },
 *   targets:      { [toObjectType]: { requested, found, unknown } }
 * }
 */
function auditDataset({ config, dataset, now, account = null }) {
  const findings = [];
  const cleared = [];
  const ruleSummaries = [];
  const totals = { rules: 0, ...emptyCounts() };

  for (const rule of enabledRules(config)) {
    const bucket = (dataset.records && dataset.records[rule.key]) || { records: [], truncated: false };
    const counts = emptyCounts();
    const violationsByCode = {};
    const ruleAssociations = (dataset.associations && dataset.associations[rule.key]) || {};
    const statusProperty = rule.flag ? rule.flag.status : null;
    const issuesProperty = rule.flag ? rule.flag.issues : null;

    for (const record of bucket.records) {
      counts.scanned += 1;
      const classification = classifyRecord(record, rule, now, config.settings);
      if (classification === 'excluded') { counts.skippedExcluded += 1; continue; }
      if (classification === 'grace') { counts.skippedGrace += 1; continue; }
      counts.evaluated += 1;

      const recordAssociations = {};
      let unverifiable = false;
      let associationsTruncated = false;
      for (const toObjectType of requiredObjectTypes(rule)) {
        const entry = ruleAssociations[toObjectType];
        if (!entry || !entry.requested[record.id] || entry.errorIds[record.id]) {
          unverifiable = true;
          continue;
        }
        recordAssociations[toObjectType] = entry.byFromId[record.id] || [];
        if (entry.truncatedIds[record.id]) associationsTruncated = true;
      }

      const previousStatus = statusProperty ? propertyValue(record.properties, statusProperty) : '';
      const previousIssues = issuesProperty ? propertyValue(record.properties, issuesProperty) : '';
      const result = unverifiable
        ? { status: STATUS.UNVERIFIED, violations: [] }
        : evaluateRecord(record, rule, recordAssociations, dataset.targets || {});
      counts[COUNT_KEY[result.status]] += 1;
      for (const violation of result.violations) violationsByCode[violation.code] = (violationsByCode[violation.code] || 0) + 1;

      const entry = {
        ruleKey: rule.key,
        ruleLabel: rule.label,
        objectTypeId: rule.objectTypeId,
        id: record.id,
        status: result.status,
        previousStatus,
        previousIssues,
        display: rule.displayProperty ? propertyValue(record.properties, rule.displayProperty) || null : null,
        createdAt: record.createdAt || null,
        associationsTruncated,
        violations: result.violations,
      };
      if (result.status !== STATUS.HEALTHY) findings.push(entry);
      else if (previousStatus && previousStatus !== STATUS.HEALTHY) cleared.push(entry);
    }

    const orphanRate = counts.evaluated ? counts.orphaned / counts.evaluated : 0;
    const tripped = counts.evaluated >= config.settings.circuitBreakerMinSample && orphanRate > config.settings.orphanRateCircuitBreaker;
    ruleSummaries.push({
      key: rule.key,
      label: rule.label,
      objectTypeId: rule.objectTypeId,
      ...counts,
      orphanRate: Math.round(orphanRate * 10000) / 10000,
      truncated: Boolean(bucket.truncated),
      violationsByCode,
      circuitBreaker: {
        tripped,
        reason: tripped
          ? `${Math.round(orphanRate * 100)}% of evaluated ${rule.label} records look orphaned (threshold ${Math.round(config.settings.orphanRateCircuitBreaker * 100)}%). That usually means a wrong object type or association label ID, so flag writes for this object are suppressed.`
          : null,
      },
    });
    totals.rules += 1;
    for (const key of Object.keys(counts)) totals[key] += counts[key];
  }

  const ruleOrder = Object.fromEntries(ruleSummaries.map((summary, index) => [summary.key, index]));
  findings.sort((a, b) => (STATUS_RANK[b.status] - STATUS_RANK[a.status]) || (ruleOrder[a.ruleKey] - ruleOrder[b.ruleKey]) || compareIds(a.id, b.id));
  cleared.sort((a, b) => (ruleOrder[a.ruleKey] - ruleOrder[b.ruleKey]) || compareIds(a.id, b.id));

  return {
    runId: `aig-${new Date(now).toISOString().replace(/[:.]/g, '-')}`,
    generatedAt: new Date(now).toISOString(),
    mode: config.mode,
    safety: describeSafety(config),
    account,
    settings: {
      gracePeriodHours: config.settings.gracePeriodHours,
      verifyTargetsExist: config.settings.verifyTargetsExist,
      orphanRateCircuitBreaker: config.settings.orphanRateCircuitBreaker,
      maxFlagUpdatesPerRun: config.settings.maxFlagUpdatesPerRun,
    },
    totals,
    rules: ruleSummaries,
    findings,
    cleared,
  };
}

function compareIds(a, b) {
  const left = String(a);
  const right = String(b);
  if (/^\d+$/.test(left) && /^\d+$/.test(right) && left.length !== right.length) return left.length - right.length;
  return left < right ? -1 : left > right ? 1 : 0;
}

/**
 * Plans flag writes. Writes are only allowed when DRY_RUN=false and FLAG_WRITES_ENABLED=true.
 * Healthy records that were never flagged are left untouched; previously flagged records that
 * are healthy again are reset to "healthy".
 */
function planFlagUpdates(report, config) {
  const writesAllowed = !config.dryRun && config.flagWritesEnabled;
  const reason = writesAllowed
    ? 'DRY_RUN=false and FLAG_WRITES_ENABLED=true'
    : config.dryRun
      ? 'DRY_RUN is on, so flag writes are only planned'
      : 'FLAG_WRITES_ENABLED is not true, so flag writes are only planned';
  const rulesByKey = Object.fromEntries(enabledRules(config).map((rule) => [rule.key, rule]));
  const summariesByKey = Object.fromEntries(report.rules.map((summary) => [summary.key, summary]));
  const checkedAt = report.generatedAt;
  const skipped = { unchanged: 0, unverified: 0, noFlagConfig: 0, circuitBreaker: 0, deferredByCap: 0 };
  let updates = [];

  for (const candidate of [...report.findings, ...report.cleared]) {
    if (candidate.status === STATUS.UNVERIFIED) { skipped.unverified += 1; continue; }
    const rule = rulesByKey[candidate.ruleKey];
    if (!rule || !rule.flag) { skipped.noFlagConfig += 1; continue; }
    if (summariesByKey[candidate.ruleKey] && summariesByKey[candidate.ruleKey].circuitBreaker.tripped) { skipped.circuitBreaker += 1; continue; }
    const properties = { [rule.flag.status]: candidate.status };
    if (rule.flag.issues) properties[rule.flag.issues] = formatIssues(candidate.violations);
    const unchanged = candidate.previousStatus === candidate.status
      && (!rule.flag.issues || candidate.previousIssues === properties[rule.flag.issues]);
    if (unchanged) { skipped.unchanged += 1; continue; }
    if (rule.flag.checkedAt) properties[rule.flag.checkedAt] = checkedAt;
    updates.push({ ruleKey: candidate.ruleKey, objectTypeId: candidate.objectTypeId, id: candidate.id, status: candidate.status, properties });
  }

  const cap = config.settings.maxFlagUpdatesPerRun;
  if (updates.length > cap) {
    skipped.deferredByCap = updates.length - cap;
    updates = updates.slice(0, cap);
  }
  return { writesAllowed, reason, updates, plannedCount: updates.length, skipped };
}

// ---- src/core/hubspot.js (embedded by scripts/build-workflow.js) ----
/**
 * HubSpot request builders and response parsers.
 *
 * The same functions run in two places: inside the n8n Code nodes (which plan requests that the
 * HTTP Request nodes execute) and inside the Node.js mirror in src/core/pipeline.js. Nothing in
 * this file performs network calls, and no request object carries the access token.
 */

const STANDARD_OBJECT_TYPE_IDS = Object.freeze({ contacts: '0-1', companies: '0-2', deals: '0-3', tickets: '0-5' });

function hubspotUrl(config, path) {
  return `${config.hubspot.baseUrl.replace(/\/+$/, '')}${path}`;
}

function chunk(list, size) {
  const chunks = [];
  for (let index = 0; index < list.length; index += size) chunks.push(list.slice(index, index + size));
  return chunks;
}

function buildAccountDetailsRequest(config) {
  return { method: 'GET', url: hubspotUrl(config, '/account-info/v3/details') };
}

/** Refuses to continue when SANDBOX_MODE=true and the token belongs to a non-sandbox portal. */
function enforceSandbox(account, config) {
  const portalId = account && account.portalId !== undefined && account.portalId !== null ? String(account.portalId) : null;
  const accountType = account && account.accountType ? String(account.accountType).toUpperCase() : null;
  if (!config.sandboxMode) return { ok: true, portalId, accountType, reason: 'SANDBOX_MODE=false, so production portals are allowed' };
  if (accountType && SANDBOX_ACCOUNT_TYPES.includes(accountType)) {
    return { ok: true, portalId, accountType, reason: `portal account type ${accountType} is a sandbox or test account` };
  }
  if (portalId && !isPlaceholder(config.hubspot.sandboxPortalId) && portalId === config.hubspot.sandboxPortalId) {
    return { ok: true, portalId, accountType, reason: 'portal ID matches HUBSPOT_SANDBOX_PORTAL_ID' };
  }
  return {
    ok: false,
    portalId,
    accountType,
    reason: `SANDBOX_MODE=true, but the connected portal (account type ${accountType || 'unknown'}) is not a sandbox or developer test account and does not match HUBSPOT_SANDBOX_PORTAL_ID. I refuse to continue.`,
  };
}

function summarizeAccount(account, gate) {
  const reported = account && typeof account.uiDomain === 'string' ? account.uiDomain.trim().toLowerCase() : '';
  const location = account && account.dataHostingLocation ? String(account.dataHostingLocation).toLowerCase() : null;
  let uiDomain = 'app.hubspot.com';
  if (/^app(?:-[a-z0-9]+)?\.hubspot\.com$/.test(reported)) uiDomain = reported;
  else if (location && location !== 'na1' && /^[a-z]{2}\d$/.test(location)) uiDomain = `app-${location}.hubspot.com`;
  return { portalId: gate.portalId, accountType: gate.accountType, uiDomain, sandboxCheck: gate.reason };
}

function recordUrl(account, objectTypeId, id) {
  if (!account || !/^\d+$/.test(String(account.portalId || ''))) return null;
  const typeId = STANDARD_OBJECT_TYPE_IDS[objectTypeId] || objectTypeId;
  return `https://${account.uiDomain || 'app.hubspot.com'}/contacts/${account.portalId}/record/${typeId}/${id}`;
}

function recordPropertiesForRule(rule) {
  const names = new Set(['hs_createdate']);
  if (rule.displayProperty) names.add(rule.displayProperty);
  if (rule.flag) for (const name of [rule.flag.status, rule.flag.issues]) if (name) names.add(name);
  for (const condition of [...rule.onlyWhen, ...rule.skipWhen]) names.add(condition.property);
  for (const requirement of rule.requirements) for (const condition of requirement.when) names.add(condition.property);
  for (const name of rule.properties) names.add(name);
  return [...names].sort();
}

/** One paginated list request per enabled rule. */
function planRecordFetch(config) {
  const { pageSize, maxRecordsPerObject } = config.settings;
  return enabledRules(config).map((rule) => ({
    stage: 'records',
    ruleKey: rule.key,
    objectTypeId: rule.objectTypeId,
    maxPages: Math.max(1, Math.ceil(maxRecordsPerObject / pageSize)),
    request: {
      method: 'GET',
      url: hubspotUrl(config, `/crm/v3/objects/${encodeURIComponent(rule.objectTypeId)}?limit=${pageSize}&archived=false&properties=${encodeURIComponent(recordPropertiesForRule(rule).join(','))}`),
    },
  }));
}

function tagRecordPage(plan, body) {
  if (!body || !Array.isArray(body.results)) throw new Error(`Unexpected HubSpot list response for ${plan.objectTypeId}: "results" is missing`);
  const next = body.paging && body.paging.next && body.paging.next.after;
  return {
    stage: 'records',
    ruleKey: plan.ruleKey,
    objectTypeId: plan.objectTypeId,
    records: body.results.map((record) => ({
      id: String(record.id),
      createdAt: record.createdAt || null,
      properties: record.properties || {},
    })),
    nextAfter: next ? String(next) : null,
  };
}

/** Groups list pages by rule, removes duplicates, applies MAX_RECORDS_PER_OBJECT and sorts by ID. */
function assembleRecords(pages, config) {
  const buckets = {};
  for (const rule of enabledRules(config)) buckets[rule.key] = { records: [], truncated: false, pages: 0, pagesWithNext: 0, seen: {} };
  for (const page of pages) {
    const bucket = buckets[page.ruleKey];
    if (!bucket) continue;
    bucket.pages += 1;
    if (page.nextAfter) bucket.pagesWithNext += 1;
    for (const record of page.records) {
      if (bucket.seen[record.id]) continue;
      bucket.seen[record.id] = true;
      bucket.records.push(record);
    }
  }
  const result = {};
  for (const [key, bucket] of Object.entries(buckets)) {
    bucket.records.sort((a, b) => compareIds(a.id, b.id));
    let truncated = bucket.pages > 0 && bucket.pagesWithNext === bucket.pages;
    let records = bucket.records;
    if (records.length > config.settings.maxRecordsPerObject) {
      records = records.slice(0, config.settings.maxRecordsPerObject);
      truncated = true;
    }
    result[key] = { records, truncated, pages: bucket.pages };
  }
  return result;
}

/** v4 batch association reads for every record that is due for evaluation. */
function planAssociationReads(config, records, now) {
  const requests = [];
  for (const rule of enabledRules(config)) {
    const bucket = records[rule.key] || { records: [] };
    const ids = bucket.records.filter((record) => classifyRecord(record, rule, now, config.settings) === 'evaluate').map((record) => record.id);
    if (!ids.length) continue;
    for (const toObjectType of requiredObjectTypes(rule)) {
      for (const group of chunk(ids, config.settings.batchSize)) {
        requests.push({
          stage: 'associations',
          ruleKey: rule.key,
          fromObjectType: rule.objectTypeId,
          toObjectType,
          request: {
            method: 'POST',
            url: hubspotUrl(config, `/crm/v4/associations/${encodeURIComponent(rule.objectTypeId)}/${encodeURIComponent(toObjectType)}/batch/read`),
            body: { inputs: group.map((id) => ({ id })) },
          },
        });
      }
    }
  }
  return requests;
}

function errorContextIds(error) {
  const context = (error && error.context) || {};
  const ids = [];
  for (const key of ['fromObjectId', 'ids', 'id', 'objectId']) {
    const value = context[key];
    if (Array.isArray(value)) ids.push(...value.map(String));
    else if (value !== undefined && value !== null) ids.push(String(value));
  }
  return ids;
}

function isNoAssociationsError(error) {
  return /NO_ASSOCIATIONS/i.test(String((error && error.subCategory) || '')) || /no .*associat/i.test(String((error && error.message) || ''));
}

function isNotFoundError(error) {
  return /NOT_FOUND/i.test(String((error && error.category) || '')) || /not found|could not get|do(?:es)? not exist/i.test(String((error && error.message) || ''));
}

/**
 * Parses a v4 batch read response. Records that HubSpot reports as having no associations count
 * as zero associations. Any other per-record error marks the record as unverifiable, so it is
 * never flagged on incomplete data.
 */
function tagAssociationResponse(plan, body) {
  if (!body || (!Array.isArray(body.results) && !Array.isArray(body.errors))) {
    throw new Error(`Unexpected HubSpot association response for ${plan.fromObjectType} -> ${plan.toObjectType}`);
  }
  const requested = plan.request.body.inputs.map((input) => String(input.id));
  const byFromId = {};
  const truncatedIds = {};
  const errorIds = {};
  for (const result of body.results || []) {
    const fromId = String(result.from && result.from.id);
    const list = byFromId[fromId] || (byFromId[fromId] = []);
    for (const to of result.to || []) {
      list.push({
        toObjectId: String(to.toObjectId),
        types: (to.associationTypes || []).map((type) => ({ category: type.category, typeId: Number(type.typeId), label: type.label ?? null })),
      });
    }
    if (result.paging && result.paging.next) truncatedIds[fromId] = true;
  }
  for (const error of body.errors || []) {
    if (isNoAssociationsError(error)) continue;
    const ids = errorContextIds(error);
    const affected = ids.length ? ids : requested.filter((id) => !byFromId[id]);
    for (const id of affected) errorIds[id] = true;
  }
  return {
    stage: 'associations',
    ruleKey: plan.ruleKey,
    fromObjectType: plan.fromObjectType,
    toObjectType: plan.toObjectType,
    requested,
    byFromId,
    truncatedIds,
    errorIds,
  };
}

/** Batch reads of associated parent records, to catch deleted parents and parent criteria (targetWhen). */
function planTargetVerification(config, records, associationResponses) {
  const byType = {};
  for (const rule of enabledRules(config)) {
    if (!records[rule.key]) continue;
    for (const requirement of rule.requirements) {
      if (!requirement.verifyTargets) continue;
      const entry = byType[requirement.toObjectType] || (byType[requirement.toObjectType] = { ids: new Set(), properties: new Set() });
      for (const condition of requirement.targetWhen) entry.properties.add(condition.property);
      for (const response of associationResponses) {
        if (response.ruleKey !== rule.key || response.toObjectType !== requirement.toObjectType) continue;
        for (const list of Object.values(response.byFromId)) {
          for (const association of list) if (matchesAssociationType(association, requirement)) entry.ids.add(association.toObjectId);
        }
      }
    }
  }
  const requests = [];
  for (const toObjectType of Object.keys(byType).sort()) {
    const entry = byType[toObjectType];
    const ids = [...entry.ids].sort(compareIds);
    if (!ids.length) continue;
    const properties = entry.properties.size ? [...entry.properties].sort() : ['hs_object_id'];
    for (const group of chunk(ids, config.settings.batchSize)) {
      requests.push({
        stage: 'targets',
        toObjectType,
        request: {
          method: 'POST',
